class DatSueldoPorCargo extends BaseDatSueldoPorCargo {
	
	/**
     *
     * @return array    Listado de los datos.
     */
    public static function obtenerDatosSueldoPorCargo() {
       return Doctrine_Query::create()
                ->from('DatSueldoPorCargo ')
				->fetchArray();
    }
	
    public static function obtenerObjDatosSueldoPorCargo($idsuerdoporcargo) {
        return Doctrine::getTable('DatSueldoPorCargo')->find($idsuerdoporcargo);
    }
    
    public static function obtenerIdSueldoporCargoXIdElementoSalarialSituacion($idelementosalarialsituacion) {
        return Doctrine_Query::create()->select('p.idsuerdoporcargo AS idsuerdoporcargo')
                        ->from('DatSueldoPorCargo p')
                        ->where('p.idelementosalarialsituacionservicio = ?', array($idelementosalarialsituacion))
                        ->fetchOne()
                        ->idsuerdoporcargo;
   }
   
   public static function obtenerIdSalarioEspecificoXIdElementoSalarialSituacion($idelementosalarialsituacion) {
        return Doctrine_Query::create()->select('p.idsalarioespecifico AS idsalarioespecifico')
                        ->from('DatSueldoPorCargo p')
                        ->where('p.idelementosalarialsituacionservicio = ?', array($idelementosalarialsituacion))
                        ->fetchOne()
                        ->idsalarioespecifico;
   }
   
   public static function obtenerIdSueldoporCargoXIdElementoSalarialCargo($idelementosalarialcargo) {
        return Doctrine_Query::create()->select('p.idsuerdoporcargo AS idsuerdoporcargo')
                        ->from('DatSueldoPorCargo p')
                        ->where('p.idelementosalarialcargo = ?', array($idelementosalarialcargo))
                        ->fetchOne()
                        ->idsuerdoporcargo;
   }
   
   public static function obtenerIdSalarioEspecificoXIdElementoSalarialCargo($idelementosalarialcargo) {
        return Doctrine_Query::create()->select('p.idsalarioespecifico AS idsalarioespecifico')
                        ->from('DatSueldoPorCargo p')
                        ->where('p.idelementosalarialcargo = ?', array($idelementosalarialcargo))
                        ->fetchOne()
                        ->idsalarioespecifico;
   }
   
   public static function existeIdSueldoporCargoXIdElementoSalarialCargo($idelementosalarialcargo) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('DatSueldoPorCargo p')
                ->where("p.idelementosalarialcargo=?", array($idelementosalarialcargo))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 2;
		 }
     }
     
    public static function existeIdSueldoporCargoXIdElementoSalarialSituacion($idelementosalarialsituacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('DatSueldoPorCargo p')
                ->where("p.idelementosalarialsituacionservicio=?", array($idelementosalarialsituacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 2;
		 }
     }
